function download(name,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('save').onclick=()=>download('roundabout.svg',$('diagram').outerHTML,'image/svg+xml');
$('json').onclick=()=>download('roundabout.json',JSON.stringify(state,null,2),'application/json');
$('png').onclick=()=>{const src=new XMLSerializer().serializeToString($('diagram'));const url=URL.createObjectURL(new Blob([src],{type:'image/svg+xml'}));const img=new Image();img.onload=()=>{const canvas=document.createElement('canvas');canvas.width=2240;canvas.height=2240;canvas.getContext('2d').drawImage(img,0,0,2240,2240);canvas.toBlob(b=>{if(b){const u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='roundabout.png';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}URL.revokeObjectURL(url)},'image/png')};img.onerror=()=>updateStatus('PNG export failed; SVG export remains available.');img.src=url};
$('reset').onclick=()=>{stopPlayback();clearScenario();state={circulating:3,diameter:38,width:4,displayScale:9.5,laneNumbers:true,showRoutes:false,showTrails:true,showConflictZones:true,vehicles:defaultVehicles(),drivingMode:'safe',minGap:8,arms:structuredClone(presets)};active='North';$('showTrails').checked=state.showTrails;$('showConflictZones').checked=state.showConflictZones;$('drivingMode').value=state.drivingMode;$('minGap').value=state.minGap;renderControls();draw();updateStatus('Reset to the requested UK lane configuration.')};
$('load').onclick=()=>$('file').click();
$('file').onchange=async e=>{stopPlayback();try{const obj=JSON.parse(await e.target.files[0].text());if(!obj.arms||!['North','East','South','West'].every(x=>obj.arms[x]?.moves?.length===obj.arms[x]?.in))throw Error('Invalid approach data');if(validateNetwork(obj).length)throw Error(validateNetwork(obj).join('; '));state={circulating:clamp(+obj.circulating||3,1,5),diameter:clamp(+obj.diameter||38,12,85),width:clamp(+obj.width||4,2.5,5),displayScale:clamp(+obj.displayScale||9.5,8,14),laneNumbers:obj.laneNumbers!==false,showRoutes:obj.showRoutes===true,showTrails:obj.showTrails!==false,showConflictZones:obj.showConflictZones!==false,vehicles:obj.vehicles||defaultVehicles(),drivingMode:obj.drivingMode==='unrestricted'?'unrestricted':'safe',minGap:Math.max(2,Math.min(30,Number(obj.minGap)||8)),arms:obj.arms};clearScenario();$('showTrails').checked=state.showTrails;$('showConflictZones').checked=state.showConflictZones;$('drivingMode').value=state.drivingMode;$('minGap').value=state.minGap;renderControls();draw();updateStatus('Configuration loaded.')}catch(err){updateStatus('Could not import JSON: '+err.message)}e.target.value=''};
renderControls();renderScenarioActivity();draw();
